Standard exercism crypto-square. Implementation:

1. Normalize: keep only alphanumeric characters and lowercase them.
2. Compute c = ceil(sqrt(n)), r = ceil(n / c).
3. For each column j, for each row i, read the character at index i*c + j, and if it exceeds n-1, use a space.
4. Join the columns with spaces.

Edge case: n = 0 → return "".

Note: c = ceil(sqrt(n)). For n=54: sqrt = 7.35, c = 8, r = ceil(54/8) = 7. Good.

Let me try writing it:

```go
package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

func Encode(pt string) string {
	var b strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(unicode.ToLower(r))
		}
	}
	s := b.String()
	n := len(s)
	if n == 0 {
		return ""
	}
	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	chunks := make([]string, c)
	for j := 0; j < c; j++ {
		var chunk strings.Builder
		for i := 0; i < r; i++ {
			idx := i*c + j
			if idx < n {
				chunk.WriteByte(s[idx])
			} else {
				chunk.WriteByte(' ')
			}
		}
		chunks[j] = chunk.String()
	}
	return strings.Join(chunks, " ")
}
```

